package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.special.Beta;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathMissingException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FDistributionImpl.inverseCumulativeProbability
 */
public class FDistributionImpl_inverseCumulativeProbability_TriageGen1Test {

    private FDistributionImpl fDistribution;
    private static final double DELTA = 1e-9;

    @Before
    public void setUp() {
        // Standard F-distribution parameters: df1=5, df2=10
        fDistribution = new FDistributionImpl(5.0, 10.0);
    }

    @Test
    public void testInverseCumulativeProbability_pIsZero() throws Exception {
        // Tests the 'if (p == 0)' branch
        double result = fDistribution.inverseCumulativeProbability(0.0);
        Assert.assertEquals(0.0, result, DELTA);
    }

    @Test
    public void testInverseCumulativeProbability_pIsOne() throws Exception {
        // Tests the 'if (p == 1)' branch
        double result = fDistribution.inverseCumulativeProbability(1.0);
        Assert.assertEquals(Double.POSITIVE_INFINITY, result, DELTA);
    }

    @Test
    public void testInverseCumulativeProbability_pInRange() throws Exception {
        // Tests the default branch: super.inverseCumulativeProbability(p)
        // For F(5, 10), p=0.5 is the median.
        double p = 0.5;
        double result = fDistribution.inverseCumulativeProbability(p);

        // Verify that the result is positive and consistent with cumulativeProbability
        Assert.assertTrue(result > 0);
        Assert.assertEquals(p, fDistribution.cumulativeProbability(result), 1e-6);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testInverseCumulativeProbability_pLessThanZero() throws Exception {
        // Tests handling of invalid input (p < 0)
        // While not explicitly in the snippet, super implementation or validation usually throws this
        fDistribution.inverseCumulativeProbability(-0.1);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testInverseCumulativeProbability_pGreaterThanOne() throws Exception {
        // Tests handling of invalid input (p > 1)
        fDistribution.inverseCumulativeProbability(1.1);
    }

    @Test
    public void testInverseCumulativeProbability_ExtremeSmallP() throws Exception {
        // Tests a very small value near zero to ensure it doesn't trigger the p==0 branch incorrectly
        double p = 1e-10;
        double result = fDistribution.inverseCumulativeProbability(p);
        Assert.assertTrue(result > 0);
    }

    @Test
    public void testInverseCumulativeProbability_ExtremeLargeP() throws Exception {
        // Tests a value very close to 1 to ensure it doesn't trigger the p==1 branch incorrectly
        double p = 1.0 - 1e-10;
        double result = fDistribution.inverseCumulativeProbability(p);
        Assert.assertTrue(Double.isFinite(result));
    }
}
